1→#!/usr/bin/env python3
"""Per-path heat from git history with exponential time decay + HTML tree.

heat(leaf) = sum over commits touching leaf of exp(-(t_now - t_c) / tau)
heat(dir)  = max heat of leaves under it
mtime(leaf) = last commit unix time touching the leaf (git "mtime")
mtime(dir)  = max mtime of leaves under it

tau = half_life / ln(2). Default half-life: 14 days.
10→
Mirror/sync repos: each sync commit is one heat event on every path it touches.

Usage:
  tools/git-heat-decay.py [--half-life DAYS] [--top N] [REPO]
  tools/git-heat-decay.py --html [OUT.html] [--half-life DAYS] [REPO]
"""

from __future__ import annotations

20→import argparse
import html
import json
import math
import subprocess
import sys
import time
from collections import defaultdict
from pathlib import Path
from typing import Any
