def git_log_touch_events(repo: Path, since_epoch: float | None) -> list[tuple[float, str]]:
    """Return list of (commit_unix_ts, path) for each path touch in history."""
    cmd = [
        "git",
        "-C",
        str(repo),
        "log",
        "--pretty=format:%ct",
40→        "--name-only",
        "--diff-filter=ACMR",
    ]
    if since_epoch is not None:
        cmd.append(f"--since={int(since_epoch)}")

    out = subprocess.check_output(cmd, text=True, errors="replace")
    events: list[tuple[float, str]] = []
    ts: float | None = None
    for line in out.splitlines():
50→        line = line.strip()
        if not line:
            continue
        if line.isdigit() and len(line) >= 9:
            ts = float(line)
            continue
        if ts is None:
            continue
        if "/" not in line and "." not in line and " " in line:
            continue
60→        events.append((ts, line))
    return events


def leaf_stats(
    events: list[tuple[float, str]],
    now: float,
    tau_seconds: float,
) -> dict[str, tuple[float, float]]:
    """path -> (heat, last_touch_unix)."""
70→    heat: dict[str, float] = defaultdict(float)
    mtime: dict[str, float] = defaultdict(float)
    for ts, path in events:
        age = max(0.0, now - ts)
        heat[path] += math.exp(-age / tau_seconds)
        if ts > mtime[path]:
            mtime[path] = ts
    return {p: (heat[p], mtime[p]) for p in heat}


80→def build_tree(stats: dict[str, tuple[float, float]]) -> dict[str, Any]:
    """Nested tree: {name, path, is_dir, heat, mtime, children?}."""
    root: dict[str, Any] = {
        "name": ".",
        "path": "",
        "is_dir": True,
        "heat": 0.0,
        "mtime": 0.0,
        "children": {},
    }
90→
    for path, (h, mt) in stats.items():
        parts = Path(path).parts
        node = root
        for i, part in enumerate(parts):
            is_last = i == len(parts) - 1
            kids = node["children"]
            if part not in kids:
                kids[part] = {
                    "name": part,
100→                    "path": "/".join(parts[: i + 1]),
                    "is_dir": not is_last,
                    "heat": 0.0,
                    "mtime": 0.0,
                    "children": {} if not is_last else None,
                }
            child = kids[part]
            if is_last:
                child["is_dir"] = False
                child["heat"] = h
110→                child["mtime"] = mt
                child["children"] = None
            else:
                child["is_dir"] = True
                if child["children"] is None:
                    child["children"] = {}
            node = child

    def finalize(node: dict[str, Any]) -> tuple[float, float]:
        kids = node.get("children")
120→        if not kids:
            return node["heat"], node["mtime"]
        max_h = 0.0
        max_mt = 0.0
        for child in kids.values():
            h, mt = finalize(child)
            if h > max_h:
                max_h = h
            if mt > max_mt:
                max_mt = mt
130→        node["heat"] = max_h
        node["mtime"] = max_mt
        return max_h, max_mt

    finalize(root)
    return root


def children_sorted(node: dict[str, Any]) -> list[dict[str, Any]]:
    kids = node.get("children") or {}
140→    items = list(kids.values())
    # folders first, then files; within each group: max/leaf mtime desc, name asc
    items.sort(key=lambda n: (0 if n["is_dir"] else 1, -n["mtime"], n["name"].lower()))
    return items


def heat_to_color(heat: float, heat_max: float) -> str:
    """Cold slate → cool blue → amber → hot red. Relative to heat_max."""
    if heat_max <= 0:
        t = 0.0
150→    else:
        t = max(0.0, min(1.0, heat / heat_max))
    # piecewise HSL-ish via RGB
    # 0.0: #1e293b (slate)  0.33: #0369a1  0.66: #d97706  1.0: #dc2626
    stops = [
        (0.0, (30, 41, 59)),
        (0.25, (3, 105, 161)),
        (0.5, (5, 150, 105)),
        (0.75, (217, 119, 6)),
        (1.0, (220, 38, 38)),
160→    ]
    for i in range(len(stops) - 1):
        t0, c0 = stops[i]
        t1, c1 = stops[i + 1]
        if t <= t1 or i == len(stops) - 2:
            u = 0.0 if t1 == t0 else (t - t0) / (t1 - t0)
            u = max(0.0, min(1.0, u))
            r = int(c0[0] + (c1[0] - c0[0]) * u)
            g = int(c0[1] + (c1[1] - c0[1]) * u)
            b = int(c0[2] + (c1[2] - c0[2]) * u)
170→            return f"rgb({r},{g},{b})"
    return "rgb(220,38,38)"


def fmt_age(now: float, mtime: float) -> str:
    if mtime <= 0:
        return "—"
    days = (now - mtime) / 86400.0
    if days < 1:
        hours = days * 24
180→        if hours < 1:
            return f"{int(days * 86400 // 60)}m ago"
        return f"{hours:.0f}h ago"
    if days < 14:
        return f"{days:.1f}d ago"
    return f"{days / 7:.1f}w ago"


def tree_to_jsonable(node: dict[str, Any], now: float) -> dict[str, Any]:
    kids = children_sorted(node) if node.get("children") else []
190→    return {
        "name": node["name"],
        "path": node["path"],
        "is_dir": node["is_dir"],
        "heat": node["heat"],
        "mtime": node["mtime"],
        "age": fmt_age(now, node["mtime"]),
        "children": [tree_to_jsonable(c, now) for c in kids] if kids else [],
    }

