  const heatMax = meta.heat_max || 1;
  document.getElementById('meta').textContent =
    meta.repo + ' · half-life ' + meta.half_life_days + 'd (τ=' + meta.tau_days.toFixed(2) +
    'd) · ' + meta.n_commits + ' commits · ' + meta.n_files + ' paths · ' +
    meta.n_events + ' touches · ' + meta.now;

  function color(heat) {{
    const t = Math.max(0, Math.min(1, heat / heatMax));
    const stops = [
      [0, [30,41,59]],
      [0.25, [3,105,161]],
      [0.5, [5,150,105]],
      [0.75, [217,119,6]],
      [1, [220,38,38]],
    ];
    for (let i = 0; i < stops.length - 1; i++) {{
      const [t0, c0] = stops[i];
      const [t1, c1] = stops[i + 1];
      if (t <= t1 || i === stops.length - 2) {{
        const u = t1 === t0 ? 0 : (t - t0) / (t1 - t0);
        const uu = Math.max(0, Math.min(1, u));
        const r = Math.round(c0[0] + (c1[0] - c0[0]) * uu);
        const g = Math.round(c0[1] + (c1[1] - c0[1]) * uu);
        const b = Math.round(c0[2] + (c1[2] - c0[2]) * uu);
        return 'rgb(' + r + ',' + g + ',' + b + ')';
