            if path not in ages:
                ages[path] = []
            if path not in mtime:
                mtime[path] = 0.0

    return dict(ages), dict(mtime), n, n_touches


def heat_from_ages(ages: list[int], tau: float) -> float:
    if not ages or tau <= 0:
        return 0.0
    return sum(math.exp(-a / tau) for a in ages)


def compute_leaf_heat(
    ages_by_path: dict[str, list[int]], half_life: float
) -> dict[str, float]:
    tau = half_life / math.log(2)
    return {p: heat_from_ages(ages, tau) for p, ages in ages_by_path.items()}


def build_tree(
    ages_by_path: dict[str, list[int]],
    mtime_by_path: dict[str, float],
    heat_by_path: dict[str, float],
) -> dict[str, Any]:
    """Nested tree; leaves carry ages[] for client-side recompute."""
    root: dict[str, Any] = {
        "name": ".",
        "path": "",
        "is_dir": True,
        "heat": 0.0,
        "mtime": 0.0,
        "ages": None,
        "children": {},
    }

    for path, ages in ages_by_path.items():
        h = heat_by_path.get(path, 0.0)
        mt = mtime_by_path.get(path, 0.0)
        parts = Path(path).parts
        node = root
        for i, part in enumerate(parts):
            is_last = i == len(parts) - 1
            kids = node["children"]
            if part not in kids:
                kids[part] = {
                    "name": part,
                    "path": "/".join(parts[: i + 1]),
                    "is_dir": not is_last,
                    "heat": 0.0,
                    "mtime": 0.0,
                    "ages": None,
                    "children": {} if not is_last else None,
                }
            child = kids[part]
            if is_last:
                child["is_dir"] = False
                child["heat"] = h
                child["mtime"] = mt
                child["ages"] = list(ages)
                child["children"] = None
            else:
                child["is_dir"] = True
                if child["children"] is None:
                    child["children"] = {}
            node = child

    def finalize(node: dict[str, Any]) -> tuple[float, float]:
        kids = node.get("children")
        if not kids:
            return node["heat"], node["mtime"]
        max_h = 0.0
        max_mt = 0.0
        for child in kids.values():
            ch, cmt = finalize(child)
            if ch > max_h:
                max_h = ch
            if cmt > max_mt:
                max_mt = cmt
        node["heat"] = max_h
        node["mtime"] = max_mt
        return max_h, max_mt

    finalize(root)
    return root


def children_sorted(node: dict[str, Any]) -> list[dict[str, Any]]:
    kids = node.get("children") or {}
    items = list(kids.values())
    # folders first, then files; within each: mtime desc, name asc
    items.sort(key=lambda n: (0 if n["is_dir"] else 1, -n["mtime"], n["name"].lower()))
    return items


# Viridis-like Y→G→B→purple anchors sampled from y-g-b-heatmap-grid.png
_HEAT_ANCHORS_RGB: list[tuple[int, int, int]] = [
    (253, 231, 37),  # #fde725 yellow (hot)
    (227, 228, 24),
    (199, 224, 32),
    (171, 220, 50),
    (143, 215, 68),
    (117, 208, 84),
    (93, 201, 99),
    (71, 192, 111),
    (53, 183, 121),
    (40, 174, 128),
    (32, 164, 134),
    (31, 154, 138),
    (33, 144, 140),
    (36, 134, 142),
    (40, 124, 142),
    (44, 114, 142),
    (49, 104, 142),
    (53, 93, 141),
    (59, 82, 139),
    (64, 70, 136),
    (68, 58, 131),
    (71, 45, 123),
    (72, 31, 113),
    (71, 17, 99),
    (68, 1, 84),  # #440154 purple (cold)
]


def _densify_palette(
    anchors: list[tuple[int, int, int]], steps_per_segment: int = 8
) -> list[tuple[int, int, int]]:
    if len(anchors) < 2:
        return list(anchors)
    out: list[tuple[int, int, int]] = []
    for i in range(len(anchors) - 1):
        c0, c1 = anchors[i], anchors[i + 1]
        for s in range(steps_per_segment):
            u = s / steps_per_segment
            out.append(
                (
                    int(round(c0[0] + (c1[0] - c0[0]) * u)),
                    int(round(c0[1] + (c1[1] - c0[1]) * u)),
                    int(round(c0[2] + (c1[2] - c0[2]) * u)),
                )
            )
    out.append(anchors[-1])
    return out


HEAT_PALETTE_RGB: list[tuple[int, int, int]] = _densify_palette(
    _HEAT_ANCHORS_RGB, steps_per_segment=8
)


def fmt_age(now: float, mtime: float) -> str:
    if mtime <= 0:
        return "never*"  # only initial commit (or unknown)
    days = (now - mtime) / 86400.0
    if days < 1:
        hours = days * 24
        if hours < 1:
            return f"{int(days * 86400 // 60)}m ago"
        return f"{hours:.0f}h ago"
    if days < 14:
        return f"{days:.1f}d ago"
    return f"{days / 7:.1f}w ago"


def tree_to_jsonable(node: dict[str, Any], now: float) -> dict[str, Any]:
    kids = children_sorted(node) if node.get("children") else []
    out: dict[str, Any] = {
        "name": node["name"],
        "path": node["path"],
        "is_dir": node["is_dir"],
        "heat": node["heat"],
        "mtime": node["mtime"],
        "age": fmt_age(now, node["mtime"]),
        "children": [tree_to_jsonable(c, now) for c in kids] if kids else [],
    }
    if not node["is_dir"]:
        out["ages"] = list(node.get("ages") or [])
    return out


def render_html(
    tree: dict[str, Any],
    *,
    repo: Path,
    half_life: float,
    now: float,
    n_touches: int,
    n_files: int,
    n_commits: int,
) -> str:
    data = tree_to_jsonable(tree, now)
    heat_max = max(float(data["heat"]), 0.0)
    # pick nearest slider position for default
    choices = list(HALF_LIFE_CHOICES)
    default_hl = min(choices, key=lambda c: abs(c - half_life))
    meta = {
        "repo": str(repo),
        "half_life": default_hl,
        "half_life_choices": choices,
        "unit": "commits",
        "now": time.strftime("%Y-%m-%d %H:%M:%S %z", time.localtime(now)),
        "n_touches": n_touches,
        "n_files": n_files,
        "n_commits": n_commits,
        "heat_max": heat_max,
        "zero_bg": ZERO_HEAT_BG,
        "note": "initial commit excluded; heat 0 → #222",
    }
    palette_js = json.dumps(HEAT_PALETTE_RGB)
    payload = json.dumps({"meta": meta, "tree": data}, ensure_ascii=False)
    payload = payload.replace("<", "\\u003c")

    legend_stops = ",".join(
        f"rgb({r},{g},{b})" for r, g, b in reversed(HEAT_PALETTE_RGB)
    )
    default_idx = choices.index(default_hl)

    return f"""<!DOCTYPE html>
<html lang="en">
